            const c=document.createElement('canvas'); c.width=1080; c.height=1350;
            const ctx=c.getContext('2d');
            ctx.fillStyle='#F8F7F2';ctx.fillRect(0,0,c.width,c.height);
            ctx.fillStyle='#111827';ctx.fillRect(0,0,c.width,180);
            ctx.fillStyle='#C9A43A';ctx.fillRect(0,177,c.width,6);
            ctx.fillStyle='#C9A43A';ctx.font='700 28px Inter, Arial';ctx.fillText('SAFE FUTURE',72,78);
            ctx.fillStyle='#FFFFFF';ctx.font='600 18px Inter, Arial';ctx.fillText('FINANCIAL PROTECTION & WEALTH ADVISORY',72,116);
            ctx.fillStyle='#111827';ctx.font='700 32px Georgia, serif';ctx.fillText('Financial Health Score',72,275);
            ctx.fillStyle='#6B7280';ctx.font='500 20px Inter, Arial';ctx.fillText('Personal financial health snapshot',72,315);
            ctx.beginPath();ctx.arc(540,570,180,0,Math.PI*2);ctx.fillStyle='#111827';ctx.fill();
            ctx.beginPath();ctx.arc(540,570,160,0,Math.PI*2);ctx.strokeStyle='#D6B64C';ctx.lineWidth=18;ctx.stroke();
            ctx.fillStyle='#FFFFFF';ctx.font='800 110px Inter, Arial';ctx.textAlign='center';ctx.fillText(String(d.score),540,595);
            ctx.font='600 25px Inter, Arial';ctx.fillText('/ 100',540,642);
