            ctx.fillStyle='#111827';ctx.font='700 30px Georgia, serif';ctx.fillText(d.nama,72,915);
            ctx.fillStyle='#4B5563';ctx.font='500 20px Inter, Arial';ctx.fillText(d.area.length?'Prioritas: '+d.area.slice(0,2).join(' • '):'Financial Health Check selesai',72,962);
            ctx.fillStyle='#6B7280';ctx.font='500 18px Inter, Arial';ctx.fillText('Bagaimana skor finansial Anda?',72,1118);
