function sfResolveAsset(path) {
    if (!path) return '';
    try { return new URL(String(path), document.baseURI).href; } catch (_) { return String(path); }
}
function sfAssetFilename(path, fallback) {
    const clean = String(path || '').split('?')[0].split('#')[0];
    const name = clean.substring(clean.lastIndexOf('/') + 1);
    return name || fallback;
}
function sfAssetLabel(kind) { return kind === 'poster' ? 'Poster' : 'Brosur'; }
function sfAssetBroken(el, kind) {
    const card = el?.closest('.sf-asset-card'); if (!card) return;
    const preview = card.querySelector('.sf-poster-preview');
    if (preview) preview.innerHTML = '<div class="sf-asset-error"><i class="fas fa-triangle-exclamation"></i><strong>'+sfAssetLabel(kind)+' belum dapat dimuat</strong><span>Pastikan folder <code>assets/solusi-produk</code> ikut di-deploy bersama file website.</span></div>';
    card.querySelectorAll('.sf-asset-actions a').forEach(a => { a.classList.add('sf-asset-disabled'); a.setAttribute('aria-disabled','true'); a.addEventListener('click',e=>e.preventDefault(),{once:true}); });
}
function sfProductAssetMarkup(data) {
    const hasPoster = !!data.poster;
    const hasBrochure = !!data.brochure;
    const posterKey = hasPoster ? sfAssetKey(data.poster) : '';
    const brochureKey = hasBrochure ? sfAssetKey(data.brochure).replace(/\.webp$/i,'.pdf') : '';
    const posterName = `${String(data.id || 'safe-future-product')}-poster.png`;
    const brochureName = `${String(data.id || 'safe-future-product')}-brosur.pdf`;
    const esc = (v) => String(v || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    const posterSrc = hasPoster ? sfAssetUrl(data.poster) : '';
    const brochureSrc = hasBrochure ? sfAssetUrl(data.brochure) : '';
    return `
      <div class="sf-prod-assets mt-5">
        <div class="flex items-center justify-between gap-3 mb-3">
          <div>
            <p class="text-[10px] font-bold uppercase tracking-[0.2em] text-gold-dark">Materi Produk</p>
            <p class="text-xs text-slate-500 mt-1">Materi resmi yang tersedia dapat dilihat dan diunduh langsung dari Safe Future.</p>
          </div>
          <span class="text-[10px] font-semibold text-slate-400">${hasPoster || hasBrochure ? 'Tersedia' : 'Segera tersedia'}</span>
        </div>
        <div class="grid ${hasPoster ? 'sm:grid-cols-2' : 'grid-cols-1'} gap-3">
          <div class="sf-asset-card ${hasPoster ? '' : 'sf-asset-empty'}">
            ${hasPoster
              ? `<a class="sf-poster-preview" href="#" onclick="event.preventDefault();sfOpenAsset('${esc(data.poster)}','${esc(posterName)}')" aria-label="Lihat poster ${esc(data.title)}"><img src="${posterSrc}" alt="Poster ${esc(data.title)}" loading="eager" decoding="async"><span class="sf-preview-badge"><i class="fas fa-expand"></i> Lihat Poster</span></a>
                 <div class="sf-asset-actions"><a href="#" onclick="event.preventDefault();sfOpenAsset('${esc(data.poster)}','${esc(posterName)}')" class="sf-asset-btn sf-asset-secondary"><i class="fas fa-eye"></i> Lihat Poster</a><a href="#" onclick="event.preventDefault();sfDownloadAsset('${esc(data.poster)}','${esc(posterName)}')" class="sf-asset-btn sf-asset-primary"><i class="fas fa-download"></i> Download Poster</a></div>`
              : `<div class="sf-asset-empty-inner"><i class="fas fa-image"></i><strong>Poster belum tersedia</strong><span>Materi poster belum termasuk dalam materi Safe Future yang tersedia saat ini.</span></div>`}
          </div>
          <div class="sf-asset-card ${hasBrochure ? '' : 'sf-asset-empty'}">
            ${hasBrochure
              ? `<div class="sf-pdf-cover"><div class="sf-pdf-icon"><i class="fas fa-file-pdf"></i></div><div><strong>Brosur Produk</strong><span>PDF materi produk yang tersedia untuk pengunjung Safe Future.</span></div></div>
                 <div class="sf-asset-actions"><a href="#" onclick="event.preventDefault();sfOpenAsset('${esc(data.brochure)}','${esc(brochureName)}')" class="sf-asset-btn sf-asset-secondary"><i class="fas fa-file-pdf"></i> Lihat Brosur</a><a href="#" onclick="event.preventDefault();sfDownloadAsset('${esc(data.brochure)}','${esc(brochureName)}')" class="sf-asset-btn sf-asset-primary"><i class="fas fa-download"></i> Download Brosur</a></div>`
              : `<div class="sf-asset-empty-inner"><i class="fas fa-file-pdf"></i><strong>Brosur belum tersedia</strong><span>Materi brosur belum termasuk dalam materi Safe Future yang tersedia saat ini.</span></div>`}
          </div>
        </div>
        ${hasPoster || hasBrochure ? `<p class="sf-asset-source-note"><i class="fas fa-circle-check"></i> Materi dipaketkan di dalam website sehingga tetap tersedia meskipun website dibuka tanpa folder asset terpisah.</p>` : ''}
      </div>`;
}
