function openProductModal(category) {
    const products = productsData[category];
    const content = document.getElementById('productModalContent');
    const modal = document.getElementById('productModal');
    if (!products || !content || !modal) return;

    const cards = products.map((data) => {
        const benefitsHTML = (data.benefits || []).map(b => `<li><i class="fas fa-circle-check"></i><span>${b}</span></li>`).join('');
        return `<article class="sf-product-detail">
          <div class="sf-product-top">
            <div class="sf-product-copy">
              <div class="sf-product-badge"><i class="fas fa-shield-halved"></i>${data.badge || 'Solusi Perlindungan'}</div>
              <h4>${data.title}</h4>
              <p class="sf-product-headline">${data.headline || ''}</p>
            </div>
            <div class="sf-price-badge"><span>${data.pricingLabel || 'Info biaya'}</span><strong>${data.pricing || 'Sesuai plan'}</strong></div>
          </div>
          <div class="sf-product-grid">
            <div class="sf-info-box"><h5><i class="fas fa-triangle-exclamation"></i> Masalah yang dijawab</h5><p>${data.problem}</p></div>
            <div class="sf-info-box"><h5><i class="fas fa-lightbulb"></i> Solusi</h5><p>${data.solution}</p></div>
          </div>
          <div class="sf-benefit-box"><h5><i class="fas fa-star"></i> Poin utama</h5><ul>${benefitsHTML}</ul></div>
          <div class="sf-fit-row"><div><span>Cocok untuk</span><p>${data.fit}</p></div><div class="sf-price-note"><span>Catatan biaya</span><p>${data.pricingNote || '*Bukan penawaran harga personal.'}</p></div></div>
          ${sfProductAssetMarkup(data)}
          <div class="sf-product-footer"><div><strong>Diagnosis sebelum rekomendasi.</strong><span>Produk bukan rekomendasi personal. Kesesuaian ditentukan setelah melihat kebutuhan, kemampuan finansial, tujuan, dan ketentuan polis.</span></div><button type="button" class="sf-consult-btn" onclick="openSfLeadModal()"><i class="fas fa-comments"></i> Konsultasikan Kebutuhan</button></div>
        </article>`;
    }).join('');

    content.innerHTML = `<div class="sf-product-modal-head"><div><span class="sf-section-kicker"><span></span> Solusi Perlindungan</span><h3>${productCategoryTitles[category] || 'Solusi Perlindungan'}</h3><p>Pilih solusi berdasarkan kebutuhan Anda. Safe Future menampilkan ringkasan manfaat, gambaran biaya, poster, dan brosur langsung di website agar Anda dapat memahami pilihan tanpa harus berpindah ke situs lain.</p></div><button type="button" class="sf-modal-close-inline" onclick="closeProductModal()" aria-label="Tutup"><i class="fas fa-times"></i></button></div>${cards}<div class="sf-disclaimer-box"><i class="fas fa-circle-info"></i><span>Informasi produk pada halaman ini bersifat edukatif dan dirangkum dari materi yang Anda sediakan. Premi/kontribusi, manfaat, underwriting, pengecualian, masa pertanggungan, dan ketentuan klaim mengikuti polis/RIPLAY yang berlaku. Angka yang ditampilkan adalah minimum atau gambaran sesuai materi yang tersedia, bukan penawaran harga personal. Nilai investasi tidak dijamin.</span></div>`;
    modal.classList.remove('hidden');
    document.body.classList.add('overflow-hidden');
}
function closeProductModal() {
    const modal = document.getElementById('productModal');
    if (!modal) return;
    modal.classList.add('hidden');
    const returningToWpr = window.__wprProductReturn === true;
    const returningToFhc = window.__fhcProductReturn === true;
    window.__wprProductReturn = false;
    window.__fhcProductReturn = false;
    const wealthOpen = !document.getElementById('wealthModal')?.classList.contains('hidden');
    if (!wealthOpen || !returningToWpr) document.body.classList.remove('overflow-hidden');
    // FHC is a page-level result, not a modal; after closing its product overlay
    // restore normal page scrolling while keeping the FHC result visible.
    if (returningToFhc) document.body.classList.remove('overflow-hidden');
}
