        //    (ntfy.sh -> Topic -> Subscribe -> Email/Webhook) sehingga setiap push juga terkirim ke email admin.
        // Ubah NTFY_TOPIC ke nilai unik Anda agar tidak ada orang lain yang bisa membaca topik ini.
        const NTFY_TOPIC = 'safe-future-leads'; // GANTI dengan topik unik, contoh: 'sf-leads-6285887836384'
        const NTFY_SERVER = 'https://ntfy.sh';
        const ADMIN_WA_NOTIF = '6285887836384'; // Nomor WA admin (dipakai di pesan notifikasi)
        function notifyLead(summary) {
            try {
                if (navigator.onLine === false) return; // offline -> lewati
                const title = 'Safe Future: Lead Baru Masuk';
                const body = summary + '\nWA Admin: ' + ADMIN_WA_NOTIF;
                fetch(NTFY_SERVER + '/' + encodeURIComponent(NTFY_TOPIC), {
                    method: 'POST',
                    body: body,
                    headers: { 'Title': title, 'Priority': 'default', 'Tags': 'mega' }
                }).catch(err => console.warn('Notifikasi ntfy gagal:', err.message));
            } catch (e) { console.warn('Notifikasi lead gagal:', e); }
        }

        // --- 5c. HAPUS RESPONDEN (per baris, dengan konfirmasi) ---
        function deleteLocalLead(index) {
            let leads = JSON.parse(localStorage.getItem('sf_leads')) || [];
            const l = leads[index];
            if (!l) return;
            if (!confirm('Hapus responden "' + (l.nama || l.wa || 'ini') + '" dari data lokal?')) return;
            leads.splice(index, 1);
            localStorage.setItem('sf_leads', JSON.stringify(leads));
            renderLeads();
        }
        async function deleteCloudLead(index) {
            const data = window.__cloudResponses || [];
            const l = data[index];
            if (!l) return;
            if (!confirm('Hapus responden "' + (l.nama || l.wa || 'ini') + '" dari Supabase?')) return;
            if (!supabaseClient || !l.id) { alert('Data ini belum memiliki id Supabase atau koneksi belum siap.'); return; }
            try {
                const { error } = await supabaseClient.from('responses').delete().eq('id', l.id);
                if (error) throw error;
                alert('Responden berhasil dihapus.');
                await loadResponsesFromSupabase();
            } catch (e) {
                console.error('Delete error:', e);
                alert('Gagal menghapus: ' + (e.message || 'koneksi gagal') + '. Periksa RLS / policy DELETE di tabel responses.');
            }
        }

        // --- 5e. EXPORT EXCEL (.xlsx via SheetJS) — semua kolom lengkap ---
        async function exportExcel() {
            let rows = [];
            let source = 'cloud (Supabase)';
            try {
                if (supabaseClient) {
                    rows = await fetchAllResponses();
                    window.__cloudResponses = rows || [];
                }
            } catch (e) { console.warn('Export: fetch cloud gagal, pakai cache/local:', e.message); }
            if (!rows.length) rows = window.__cloudResponses || [];
            if (!rows.length) {
                rows = JSON.parse(localStorage.getItem('sf_leads')) || [];
                source = 'lokal (browser ini)';
            }
            if (!rows.length) { alert('Belum ada data untuk diexport. Pastikan tabel responses berisi data dan policy SELECT aktif.'); return; }

            const raw = r => (r && typeof r === 'object' && r.raw && typeof r.raw === 'object') ? r.raw : {};
            const g = (r, snake, camel) => {
                const rr = raw(r);
                if (r[snake] !== undefined && r[snake] !== null && r[snake] !== '') return r[snake];
                if (r[camel] !== undefined && r[camel] !== null && r[camel] !== '') return r[camel];
                if (rr[camel] !== undefined && rr[camel] !== null && rr[camel] !== '') return rr[camel];
                return '';
            };
            const arrJoin = v => {
                if (Array.isArray(v)) return v.map(x => {
                    if (typeof x === 'string') return x;
                    if (x && typeof x === 'object') return x.title || x.name || x.label || x.goal || JSON.stringify(x);
                    return x;
                }).join('; ');
                if (v && typeof v === 'object') return JSON.stringify(v);
                return v == null ? '' : v;
            };

            const data = rows.map(r => {
                const rr = raw(r);
                return {
                    'Timestamp': g(r, 'created_at', 'timestamp'),
                    'Tanggal Lahir': g(r, 'dob', 'dob') || (rr.dob || ''),
                    'Segment': r.segment || 'FHC',
                    'Nama': g(r, 'nama', 'nama'),
                    'WhatsApp': g(r, 'wa', 'wa'),
                    'Kota': g(r, 'kota', 'kota'),
                    'Pekerjaan': g(r, 'pekerjaan', 'pekerjaan'),
                    'Status Pernikahan': g(r, 'status', 'status'),
                    'Jumlah Anak': g(r, 'anak', 'anak'),
                    'Usia': g(r, 'usia', 'usiaSekarang'),
                    'Total Income': g(r, 'total_income', 'totalIncome'),
                    'Expense': g(r, 'expense', 'expense'),
                    'Aset Likuid': g(r, 'aset_likuid', 'asetLikuid'),
                    'Aset Investasi': g(r, 'aset_investasi', 'asetInvestasi'),
                    'Aset Non-Likuid': g(r, 'aset_nonlikuid', 'asetNonLikuid'),
                    'Total Wealth': g(r, 'total_wealth', 'totalWealth'),
                    'Total Utang': g(r, 'total_utang', 'totalUtang'),
                    'UP Jiwa': g(r, 'up_jiwa', 'upJiwa'),
                    'Limit Kesehatan': g(r, 'limit_health', 'limitHealth'),
                    'Kritis FHC': g(r, 'kritis_fhc', 'kritisFHC'),
                    'CI Gap': g(r, 'ci_gap', 'ciGap'),
                    'Dana Pendidikan': g(r, 'dana_pendidikan', 'danaPendidikan'),
                    'Income Replacement Years': g(r, 'income_replacement_years', 'incomeReplacementYears'),
                    'Final Expense': g(r, 'final_expense', 'finalExpense'),
                    'Income Replacement Years': g(r, 'income_replacement_years', 'incomeReplacementYears'),
                    'Final Expense': g(r, 'final_expense', 'finalExpense'),
                    'Usia Pensiun': g(r, 'usia_pensiun', 'usiaPensiun'),
                    'Ret Mode': g(r, 'ret_mode', 'retMode'),
                    'Ret Monthly Target': g(r, 'ret_monthly_target', 'retMonthlyTarget'),
                    'Ret Lump Target': g(r, 'ret_lump_target', 'retLumpTarget'),
                    'Ret Kontribusi': g(r, 'ret_contribution', 'retContribution'),
                    'Goals': arrJoin(r.goals || rr.finGoals || rr.goals),
                    'Overall Score': g(r, 'overall_score', 'overallScore'),
                    'Prioritas': arrJoin(r.priorities || rr.priorities),
                    'Insurance Protection': g(r, 'insurance_protection', 'insuranceProtection'),
                    'Total Need': g(r, 'total_need', 'totalNeed'),
                    'Protection Gap': g(r, 'protection_gap', 'protectionGap'),
                    'Total Gap (Moderat)': g(r, 'total_gap_moderat', 'totalGapModerat'),
                    'Retirement Gap Today': g(r, 'retirement_gap_today', 'retirementGapToday'),
                    'WPR Score': g(r, 'wpr_score', 'wprScore'),
                    'WPR Networth': g(r, 'wpr_networth', 'netWorth'),
                    'WPR Prot Coverage': g(r, 'wpr_prot_coverage', 'protCoverage')
                };
            });

            if (!window.XLSX && window.__loadSheetJS) {
                try { await window.__loadSheetJS; } catch(e) { console.warn('SheetJS loader gagal:', e); }
            }
            if (typeof XLSX === 'undefined') {
                // Last-resort export so the lead data is never trapped in the UI.
                const headers = Object.keys(data[0] || {});
                const csv = [headers.join(',')].concat(data.map(row => headers.map(h => {
                    const v = row[h] == null ? '' : String(row[h]).replace(/"/g,'""');
                    return '"' + v + '"';
                }).join(','))).join('\n');
                const blob = new Blob(["\\ufeff" + csv], {type:'text/csv;charset=utf-8;'});
                const a = document.createElement('a');
                a.href = URL.createObjectURL(blob);
                a.download = 'safe-future-leads-' + new Date().toISOString().slice(0,10) + '.csv';
                document.body.appendChild(a); a.click(); a.remove();
                alert('SheetJS tidak tersedia. Data tetap berhasil diekspor sebagai CSV yang dapat dibuka di Excel.');
                return;
            }
            const ws = XLSX.utils.json_to_sheet(data);
            const wb = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(wb, ws, 'Responden');
            const fname = 'safe-future-leads-' + new Date().toISOString().slice(0, 10) + '.xlsx';
            XLSX.writeFile(wb, fname);
            console.log('Excel export selesai (' + data.length + ' baris, sumber: ' + source + ')');
        }  

        // --- 5f. AUTO-REFRESH DASHBOARD (list leads selalu muncul & terbaru) ---  
