        // --- 5d. ADMIN LOGIN (Supabase admins table) ---
        async function sha256Hash(text) {  
            try {  
                const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));  
                return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');  
            } catch (e) {  
                let hash = 0, i, chr;  
                for (i = 0; i < text.length; i++) { chr = text.charCodeAt(i); hash = ((hash << 5) - hash) + chr; hash |= 0; }  
                return 'djb2_' + Math.abs(hash).toString(16);  
            }  
        }  

        async function adminLogin() {  
            const msg = document.getElementById('adminLoginMsg');  
            msg.classList.add('hidden');  
            const username = (document.getElementById('adminUsername').value || '').trim();  
            const password = document.getElementById('adminPassword').value || '';  
            if (!username || !password) { msg.textContent = 'Isi username dan password.'; msg.classList.remove('hidden'); return; }  
            if (!supabaseClient) { msg.textContent = 'Koneksi Supabase belum tersedia. Pastikan halaman dimuat dari HTTPS dan SQL setup sudah dijalankan.'; msg.classList.remove('hidden'); return; }  
            try {  
                const hash = await sha256Hash(password);  
                const { data: verified, error } = await supabaseClient.rpc('verify_admin_login', {
                    p_username: username,
                    p_password_hash: hash
                });
                if (error) throw error;
                if (verified !== true) { msg.textContent = 'Username atau password salah.'; msg.classList.remove('hidden'); return; }
                sessionStorage.setItem('sf_admin', username);
                sfAdminSession = { username, passwordHash: hash }; window.__sfAdminSession = sfAdminSession;
                supabaseClient = buildSupabaseClient(username);
                window.supabaseClient = supabaseClient;
                document.getElementById('adminLoginCard').classList.add('hidden');  
                document.getElementById('adminPanel').classList.remove('hidden');  
                renderAdminStats(window.__cloudResponses || []);
                await loadResponsesFromSupabase();  
                loadVisitorStats();  
                startAdminAutoRefresh();
                if (window.sf5RefreshCRM) setTimeout(() => window.sf5RefreshCRM(), 250);
            } catch (e) {  
                console.error('Login error:', e);  
                msg.textContent = 'Gagal login: ' + (e.message || 'koneksi gagal') + '. Pastikan tabel admins sudah dibuat.';  
                msg.classList.remove('hidden');  
            }  
        }  

        // Helper: fetch SEMUA baris dari tabel responses (paginasi, tanpa batas terpotong)
        async function fetchAllResponses() {
            const username = sessionStorage.getItem('sf_admin') || '';
            const passwordHash = sfAdminSession.passwordHash || '';
            // Primary path: PostgREST RPC with SECURITY DEFINER. This bypasses
            // the fragile table-level RLS/header dependency that caused the
            // dashboard to remain stuck on "Memuat data responden…".
            if (username && passwordHash) {
                try {
                    const rr = await Promise.race([
                        fetch(SUPABASE_URL + '/rest/v1/rpc/get_admin_responses', {
                            method: 'POST',
                            headers: {
                                'apikey': SUPABASE_KEY,
                                'Authorization': 'Bearer ' + SUPABASE_KEY,
                                'Content-Type': 'application/json',
                                'Accept': 'application/json'
                            },
                            body: JSON.stringify({ p_username: username, p_password_hash: passwordHash })
                        }),
                        new Promise((_, reject) => setTimeout(() => reject(new Error('Admin RPC HTTP timeout')), 12000))
                    ]);
                    if (rr.ok) {
                        const data = await rr.json();
                        if (Array.isArray(data)) return data;
                    } else {
                        console.warn('Admin RPC HTTP failed:', rr.status);
                    }
                } catch (e) {
                    console.warn('Admin RPC HTTP unavailable:', e);
                }
                try {
                    if (supabaseClient?.rpc) {
                        const rpc = await Promise.race([
                            supabaseClient.rpc('get_admin_responses', {
                                p_username: username,
                                p_password_hash: passwordHash
                            }),
                            new Promise((_, reject) => setTimeout(() => reject(new Error('Admin RPC timeout')), 10000))
                        ]);
                        if (!rpc.error && Array.isArray(rpc.data)) return rpc.data;
                        if (rpc.error) console.warn('Admin RPC failed, using legacy query:', rpc.error.message);
                    }
                } catch (e) {
                    console.warn('Admin RPC unavailable, using legacy query:', e);
                }
            }
            const PAGE = 500;
            const timeout = (promise, ms=10000) => Promise.race([promise, new Promise((_,rej)=>setTimeout(()=>rej(new Error('Supabase timeout')),ms))]);
            let all = [], from = 0;
            const adminUser = sessionStorage.getItem('sf_admin') || '';
            while (true) {
                let res;
                try {
                    res = await timeout(supabaseClient.from('responses').select('*').order('created_at', {ascending:false}).range(from, from+PAGE-1));
                } catch (e) {
                    res = {data:null,error:e};
                }
                if (res.error) {
                    try {
                        res = await timeout(supabaseClient.from('responses').select('*').range(from, from+PAGE-1));
                    } catch (e) { res = {data:null,error:e}; }
                }
                if (res.error) {
                    // REST fallback keeps the admin dashboard usable if the JS client hangs/fails.
                    const url = SUPABASE_URL + '/rest/v1/responses?select=*&order=created_at.desc&offset='+from+'&limit='+PAGE;
                    const rr = await timeout(fetch(url,{headers:{'apikey':SUPABASE_KEY,'Authorization':'Bearer '+SUPABASE_KEY,'x-sf-admin':adminUser,'Accept':'application/json'}}));
                    if(!rr.ok) throw new Error('Supabase HTTP '+rr.status);
                    res = {data: await rr.json(), error:null};
                }
                const data = Array.isArray(res.data) ? res.data : [];
                if (!data.length) break;
                all = all.concat(data);
                if (data.length < PAGE) break;
                from += PAGE;
            }
            return all;
        }

        // Render summary + list dari SATU sumber data yang sama (tidak ada sumber terpisah).
        function renderCloudTable(data) {
            const table = document.getElementById('leadsTable');
            if (!table) return;
            const rows = data || [];
            renderAdminStats(rows);
            if (!rows.length) {
                table.innerHTML = '<tr><td colspan="7" class="p-8 text-center text-slate-400">Belum ada responden tersimpan di Supabase. Data baru akan muncul otomatis di sini.</td></tr>';
                return;
            }
            table.innerHTML = rows.map((l, i) => {
                const seg = l.segment || 'FHC';
                const segBadge = seg === 'CONTACT'
                    ? '<span class="inline-flex items-center gap-1.5 text-[10px] font-bold px-2.5 py-1 rounded-full bg-emerald-50 text-emerald-700 border border-emerald-100"><i class="fas fa-envelope text-[9px]"></i>Pesan</span>'
                    : (seg === 'WPR' || seg === 'Affluent'
                    ? '<span class="inline-flex items-center gap-1.5 text-[10px] font-bold px-2.5 py-1 rounded-full bg-amber-50 text-gold-dark border border-amber-200"><i class="fas fa-gem text-[9px]"></i>W&PR</span>'
                    : '<span class="inline-flex items-center gap-1.5 text-[10px] font-bold px-2.5 py-1 rounded-full bg-blue-50 text-blue-600 border border-blue-100"><i class="fas fa-stethoscope text-[9px]"></i>FHC</span>');
                const need = l.total_need != null ? Number(l.total_need).toLocaleString('id-ID') : '\u2014';
                const gap = l.protection_gap != null ? Number(l.protection_gap).toLocaleString('id-ID') : '\u2014';
                const tgl = l.created_at ? new Date(l.created_at).toLocaleString('id-ID') : '\u2014';
                return `<tr class="border-b border-slate-100 hover:bg-slate-50 transition">` +
                    `<td class="p-5">${segBadge}</td>` +
                    `<td class="p-5 font-semibold text-navy">${l.nama || '\u2014'}</td>` +
                    `<td class="p-5 text-slate-600">${tgl}</td>` +
                    `<td class="p-5 text-slate-600">${l.usia != null ? l.usia : '\u2014'}</td>` +
                    `<td class="p-5 text-slate-600">${need}</td>` +
                    `<td class="p-5 text-red-600 font-semibold">${gap}</td>` +
                    `<td class="p-5 space-x-2 whitespace-nowrap">` +
                        `<button onclick="viewCloudDetail(${i})" class="bg-navy text-white px-4 py-2 rounded-md text-xs hover:bg-navy-light transition"><i class="fas fa-eye mr-1"></i>Detail</button>` +
                        `<button onclick="deleteCloudLead(${i})" class="bg-red-500 text-white px-4 py-2 rounded-md text-xs hover:bg-red-600 transition"><i class="fas fa-trash mr-1"></i>Hapus</button>` +
                    `</td>` +
                `</tr>`;
            }).join('');
        }

        async function loadResponsesFromSupabase() {
            const table = document.getElementById('leadsTable');
            const statusEl = document.getElementById('adminDataStatus');
            if (statusEl) statusEl.textContent = 'Memuat data responden dari Supabase\u2026';
            if (table) table.innerHTML = '<tr><td colspan="7" class="p-8 text-center text-slate-400"><i class="fas fa-spinner fa-spin mr-2"></i>Memuat data responden\u2026</td></tr>';
            if (!supabaseClient) {
                renderLeads(); // fallback localStorage
                if (statusEl) statusEl.textContent = 'Supabase tidak tersedia \u2014 menampilkan data lokal browser ini.';
                return;
            }
            try {
                const data = await fetchAllResponses();
                if (!Array.isArray(data)) throw new Error('fetch gagal');
                window.__cloudResponses = Array.isArray(data) ? data : [];
                if (typeof window.renderCloudTable === 'function') window.renderCloudTable(window.__cloudResponses);
                else renderCloudTable(window.__cloudResponses);
                renderAdminStats(window.__cloudResponses);
                if (statusEl) statusEl.textContent = window.__cloudResponses.length ? (window.__cloudResponses.length + ' responden dari cloud (Supabase) — diperbarui otomatis.') : 'Cloud aktif — belum ada responden.';
            } catch (e) {
                console.error('Load responses error:', e);
                // JANGAN hapus data cloud yang sudah pernah dimuat \u2014 pertahankan data terakhir agar tidak "hilang".
                const cached = window.__cloudResponses;
                if (Array.isArray(cached) && cached.length) {
                    renderCloudTable(cached);
                    if (statusEl) statusEl.textContent = 'Refresh gagal (' + (e.message || 'koneksi gagal') + ') \u2014 menampilkan ' + cached.length + ' responden terakhir yang tersimpan.';
                    return;
                }
                // Belum ada data cloud sama sekali \u2192 fallback localStorage agar tidak kosong tanpa penjelasan.
                renderLeads();
                if (table) table.innerHTML = '<tr><td colspan="7" class="p-8 text-center text-red-400">Gagal memuat cloud: ' + (e.message || 'koneksi gagal') + '. Menampilkan data lokal browser ini.</td></tr>';
                if (statusEl) statusEl.textContent = 'Koneksi cloud gagal \u2014 menampilkan data lokal.';
            }
        }

        function viewCloudDetail(index){const data=window.__cloudResponses||[];const l=data[index];if(!l)return;sfShowDetail(l,l.segment==='Affluent'||l.segment==='WPR'||l.wpr_score!=null||(l.raw&&l.raw.wprScore!=null));}

        // --- 6. SCROLL ANIMATION & MOBILE MENU ---  
        const observer = new IntersectionObserver((entries) => {  
            entries.forEach(entry => {  
                if (entry.isIntersecting) entry.target.classList.add('visible');  
            });  
        }, { threshold: 0.1 });  
        document.querySelectorAll('.fade-in').forEach(el => observer.observe(el));  
        // Safety fallback: never leave content permanently invisible (e.g. no-JS observers)  
        window.addEventListener('load', () => {  
            setTimeout(() => {  
                document.querySelectorAll('.fade-in:not(.visible)').forEach(el => el.classList.add('visible'));  
            }, 1200);  
        });  
        setTimeout(() => {  
            document.querySelectorAll('.fade-in:not(.visible)').forEach(el => el.classList.add('visible'));  
        }, 3000);
  
